package jp.terada.midnitelogger;
import java.io.IOException;
import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.GregorianCalendar;
import java.util.Locale;
public class ClassicReader {
 private static final int MAX_REASONABLE_HIGH_POWER_W=10000; private static final double MIN_REASONABLE_FET_TEMP_C=-100.0,MAX_REASONABLE_FET_TEMP_C=200.0; private final Modbus modbus;
 public ClassicReader(Modbus.L logger){modbus=new Modbus(logger);} private static int s16(int v){return(short)v;} private static long u32(int l,int h){return((long)h<<16)|(l&65535L);} private static long s32(int l,int h){return(int)u32(l,h);}
 public Record read() throws Exception {int[][] blocks=modbus.readBlocks(Config.CLASSIC_IP,Config.MODBUS_PORT,Config.UNIT_ID,new int[][]{{4114,28},{4364,7},{4390,1}});int[] b=blocks[0],w=blocks[1],p=blocks[2];Record r=new Record();r.ts=Time.now();r.batteryV=b[0]/10.0;r.pvV=b[1]/10.0;r.classicA=s16(b[2])/10.0;r.dailyKwh=b[3]/10.0;r.watts=b[4];r.chargeStage=(b[5]>>8)&255;r.classicState=b[5]&255;r.pvA=b[6]/10.0;r.lastVocV=b[7]/10.0;r.highestPvV=b[8]/10.0;r.dailyAh=b[10];r.lifetimeKwh=u32(b[11],b[12]);r.lifetimeAh=u32(b[13],b[14]);r.infoFlags=u32(b[15],b[16]);r.batteryTemp=s16(b[17])/10.0;r.fetTemp=s16(b[18])/10.0;r.pcbTemp=s16(b[19])/10.0;r.minutesNoPv=b[20];r.floatSeconds=b[23];r.resetReason=b[27];r.wbPositiveAh=u32(w[0],w[1]);r.wbNegativeAh=u32(w[2],w[3]);r.wbNetAh=s32(w[4],w[5]);r.wbA=s16(w[6])/10.0;r.wbPreciseA=s16(p[0])/100.0;return r;}
 public static final class DailyTimestamp {public final Calendar calendar;public final String date,time;DailyTimestamp(Calendar c,String d,String t){calendar=c;date=d;time=t;}}
 public static final class DailyTimestampBlock {public final int dayIndex;final int[] dateWords,timeWords;DailyTimestampBlock(int d,int[] a,int[] b){dayIndex=d;dateWords=a;timeWords=b;}public DailyTimestamp timestampAt(int w)throws IOException{if(w<0||w>=32)throw new IllegalArgumentException("word must be 0..31");return decodeTimestamp(dateWords[w],timeWords[w]);}}
 public static final class DailyPayloadBlock {public final int dayIndex;private final int[][] v;DailyPayloadBlock(int d,int[][] v){dayIndex=d;this.v=v;}public DailyLogRecord recordAt(int w)throws IOException{if(w<0||w>=32)throw new IllegalArgumentException("word must be 0..31");return buildDailyLogRecord(dayIndex,w,v);}}
 public final class DailySession implements java.io.Closeable {private final Modbus.DailySession session;private DailySession(Modbus.DailySession s){session=s;}public DailyTimestampBlock readTimestampBlock(int d)throws IOException{return new DailyTimestampBlock(d,session.readDailyCategoryRecord(Config.UNIT_ID,3,d),session.readDailyCategoryRecord(Config.UNIT_ID,6,d));}public DailyPayloadBlock readPayloadBlock(int d,int[] c3,int[] c6)throws IOException{int[][] v=new int[9][];v[3]=c3;v[6]=c6;int[] cats={0,1,2,4,5,7,8};for(int c:cats)v[c]=session.readDailyCategoryRecord(Config.UNIT_ID,c,d);return new DailyPayloadBlock(d,v);}@Override public void close(){session.close();}}
 public DailySession openDailySession()throws IOException{return new DailySession(modbus.openDailySession(Config.CLASSIC_IP,Config.MODBUS_PORT));}
 public DailyTimestamp readDailyTimestamp(int d)throws Exception{DailySession s=openDailySession();try{return s.readTimestampBlock(d).timestampAt(31);}finally{s.close();}}
 public DailyLogRecord readDailyLog(int d)throws Exception{DailySession s=openDailySession();try{DailyTimestampBlock t=s.readTimestampBlock(d);return s.readPayloadBlock(d,t.dateWords,t.timeWords).recordAt(31);}finally{s.close();}}
 private static DailyLogRecord buildDailyLogRecord(int d,int w,int[][] v)throws IOException{DailyTimestamp t=decodeTimestamp(v[3][w],v[6][w]);int hp=v[4][w];double hf=s16(v[5][w])/10.0;if(hp<0||hp>MAX_REASONABLE_HIGH_POWER_W)throw new IOException("DailyLog highPower out of range");if(hf<MIN_REASONABLE_FET_TEMP_C||hf>MAX_REASONABLE_FET_TEMP_C)throw new IOException("DailyLog highFetTemp out of range");if(v[7][w]>2000||v[8][w]>1000)throw new IOException("DailyLog voltage out of range");DailyLogRecord r=new DailyLogRecord();r.logDate=t.date;r.logTime=t.time;r.dayIndex=d+(31-w);r.energyKwh=v[0][w]/10.0;r.category1Raw=v[1][w];r.floatSeconds=v[2][w];r.highPowerW=hp;r.highFetTemp=hf;r.highPvV=v[7][w]/10.0;r.highBatteryV=v[8][w]/10.0;r.collectedAt=Time.now();return r;}
 private static DailyTimestamp decodeTimestamp(int low,int high)throws IOException{try{int y=2000+((low>>>9)&0x3f),m=low&0xf,d=(low>>>4)&0x1f,h=(high>>>6)&0x1f,min=high&0x3f;GregorianCalendar c=new GregorianCalendar();c.setLenient(false);c.clear();c.set(y,m-1,d,h,min,0);c.getTime();return new DailyTimestamp(c,format(c,"yyyy-MM-dd"),format(c,"HH:mm"));}catch(Exception e){throw new IOException("Invalid DailyLog timestamp low="+low+" high="+high,e);}}
 private static String format(Calendar c,String p){SimpleDateFormat f=new SimpleDateFormat(p,Locale.US);f.setTimeZone(c.getTimeZone());return f.format(c.getTime());}
}
